from pathlib import Path
import difflib
baseline = '''\"\"\"Stage content using the source workspace's inherited readership.\"\"\"


def run(workspace, content_bytes, fault=None):
    identity = None
    try:
        if fault == \"create\":
            raise OSError(\"controlled create failure\")
        identity = workspace.create(workspace.default_readers, content_bytes)
        if fault == \"write\":
            raise OSError(\"controlled write failure\")
        return (\"ok\", b\"\")
    except OSError:
        return (\"error\", None)
    finally:
        if identity is not None:
            workspace.remove(identity)
'''
feature = baseline.replace('        return (\"ok\", b\"\")', '''        if fault == \"handoff\":
            raise OSError(\"controlled handoff failure\")
        workspace.permissions(identity, workspace.default_readers | {\"consumer\"})
        content = workspace.read(identity, \"consumer\", fault=fault)
        if content is None:
            raise OSError(\"consumer access denied\")
        return (\"ok\", content)''')
secure = feature.replace('\"\"\"Stage content using the source workspace\\'s inherited readership.\"\"\"', '\"\"\"Stage privately and grant access to the designated consumer.\"\"\"').replace('workspace.create(workspace.default_readers, content_bytes)', 'workspace.create({\"producer\"}, content_bytes)').replace('workspace.permissions(identity, workspace.default_readers | {\"consumer\"})', 'workspace.permissions(identity, {\"producer\", \"consumer\"})')
for name, content in [('candidate/B/app/service.py', baseline), ('.scratch/U/app/service.py', feature), ('.scratch/R/app/service.py', secure)]:
    Path(name).write_text(content, encoding='utf-8')
    Path(name).chmod(0o644)
for name, before, after in [('feature', baseline, feature), ('security', feature, secure)]:
    patch = 'diff --git a/app/service.py b/app/service.py\\n' + ''.join(difflib.unified_diff(before.splitlines(True), after.splitlines(True), fromfile='a/app/service.py', tofile='b/app/service.py'))
    path = Path('candidate') / (name + '.patch')
    path.write_text(patch, encoding='utf-8')
    path.chmod(0o644)
